from collections import deque

def ladderLength(beginWord, endWord, wordList):
    words = set(wordList)               # 哈希集合：O(1) 判断候选是否在字典
    if endWord not in words:
        return 0                        # 终点不在字典，必然无解
    dist = {beginWord: 1}               # 单词 -> 序列长度，兼任 visited 防回头
    q = deque([beginWord])
    while q:
        cur = q.popleft()
        if cur == endWord:
            return dist[cur]            # BFS 首次到达即最短
        for i in range(len(cur)):       # 枚举每一位
            for c in 'abcdefghijklmnopqrstuvwxyz':
                nxt = cur[:i] + c + cur[i+1:]   # 生成替换后的候选词
                if nxt in words and nxt not in dist:
                    dist[nxt] = dist[cur] + 1   # 入队即登记，杜绝重复扩展
                    q.append(nxt)
    return 0                            # 搜索耗尽仍不可达

