class Solution {
public:
    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
        unordered_set<string> words(wordList.begin(), wordList.end()); // 哈希集合：O(1) 判断候选单词是否在字典
        if (!words.count(endWord)) return 0;  // 终点不在字典里，必然无法转化
        // dist: 单词 -> 序列长度，兼任 visited 防回头；起点自身也计入序列长度
        unordered_map<string, int> dist{{beginWord, 1}};
        queue<string> q;
        q.push(beginWord);
        while (!q.empty()) {
            string cur = q.front();
            q.pop();
            if (cur == endWord) return dist[cur];  // BFS 首次到达即最短，直接返回
            // 枚举每一位，尝试替换成 26 个字母构造相邻单词
            for (int i = 0; i < (int)cur.size(); ++i) {
                string nxt = cur;
                for (char c = 'a'; c <= 'z'; ++c) {
                    if (c == nxt[i]) continue;
                    nxt[i] = c;
                    // 在字典中且未访问 = 相邻节点
                    if (words.count(nxt) && !dist.count(nxt)) {
                        dist[nxt] = dist[cur] + 1;  // 入队即登记，杜绝重复扩展
                        q.push(nxt);
                    }
                }
            }
        }
        return 0;  // 搜索耗尽仍不可达，说明不存在转化序列
    }
};

