// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：beginWord endWord
//   第二行：n（字典单词数）
//   接下来 n 行：每行一个字典单词
// 输出格式：一个整数，最短转化序列的单词数目；不存在输出 0
#include <iostream>
#include <queue>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <vector>

using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关闭同步，读入更快
    cin.tie(nullptr);

    string begin, end;
    int n;
    cin >> begin >> end >> n;
    unordered_set<string> words;   // 哈希集合：O(1) 判断候选是否在字典
    for (int i = 0; i < n; ++i) {
        string w;
        cin >> w;
        words.insert(std::move(w));
    }
    if (!words.count(end)) {       // 终点不在字典，必然无解
        cout << 0 << endl;
        return 0;
    }

    unordered_map<string, int> dist{{begin, 1}};  // 单词 -> 序列长度，兼任 visited
    queue<string> q;
    q.push(begin);
    int ans = 0;
    while (!q.empty()) {
        string cur = q.front();
        q.pop();
        if (cur == end) {          // BFS 首次到达即最短
            ans = dist[cur];
            break;
        }
        for (int i = 0; i < (int)cur.size(); ++i) {  // 枚举每一位替换成 26 个字母
            string nxt = cur;
            for (char c = 'a'; c <= 'z'; ++c) {
                if (c == nxt[i]) continue;
                nxt[i] = c;
                if (words.count(nxt) && !dist.count(nxt)) {
                    dist[nxt] = dist[cur] + 1;    // 入队即登记，防重复扩展
                    q.push(nxt);
                }
            }
        }
    }
    cout << ans << endl;
    return 0;
}

