class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> words = new HashSet<>(wordList);  // 哈希集合：O(1) 判断候选单词是否在字典
        if (!words.contains(endWord)) return 0;       // 终点不在字典里，必然无法转化
        // dist: 单词 -> 序列长度，兼任 visited 防回头；起点自身也计入序列长度
        Map<String, Integer> dist = new HashMap<>();
        dist.put(beginWord, 1);
        Queue<String> q = new ArrayDeque<>();
        q.offer(beginWord);
        while (!q.isEmpty()) {
            String cur = q.poll();
            if (cur.equals(endWord)) return dist.get(cur);  // BFS 首次到达即最短
            // 枚举每一位替换成 26 个字母，构造相邻单词
            for (int i = 0; i < cur.length(); i++) {
                char[] arr = cur.toCharArray();
                for (char c = 'a'; c <= 'z'; c++) {
                    if (c == arr[i]) continue;
                    arr[i] = c;
                    String nxt = new String(arr);
                    // 在字典中且未访问 = 相邻节点
                    if (words.contains(nxt) && !dist.containsKey(nxt)) {
                        dist.put(nxt, dist.get(cur) + 1);  // 入队即登记，杜绝重复扩展
                        q.offer(nxt);
                    }
                }
            }
        }
        return 0;  // 搜索耗尽仍不可达，说明不存在转化序列
    }
}

