/**
 * @param {string} beginWord
 * @param {string} endWord
 * @param {string[]} wordList
 * @return {number}
 */
var ladderLength = function (beginWord, endWord, wordList) {
  const words = new Set(wordList);        // 哈希集合：O(1) 判断候选单词是否在字典
  if (!words.has(endWord)) return 0;      // 终点不在字典里，必然无法转化
  const dist = new Map([[beginWord, 1]]); // 单词 -> 序列长度，兼任 visited；起点计入长度
  const q = [beginWord];
  while (q.length) {
    const cur = q.shift();
    if (cur === endWord) return dist.get(cur); // BFS 首次到达即最短，直接返回
    // 枚举每一位替换成 26 个字母，构造相邻单词
    for (let i = 0; i < cur.length; i++) {
      for (let c = 97; c <= 122; c++) {    // 'a'..'z'
        const nxt = cur.slice(0, i) + String.fromCharCode(c) + cur.slice(i + 1);
        // 在字典中且未访问 = 相邻节点
        if (words.has(nxt) && !dist.has(nxt)) {
          dist.set(nxt, dist.get(cur) + 1);    // 入队即登记，杜绝重复扩展
          q.push(nxt);
        }
      }
    }
  }
  return 0;  // 搜索耗尽仍不可达，说明不存在转化序列
};

