func ladderLength(beginWord string, endWord string, wordList []string) int {
	// 哈希集合：O(1) 判断候选单词是否在字典
	words := map[string]bool{}
	for _, w := range wordList {
		words[w] = true
	}
	if !words[endWord] { // 终点不在字典里，必然无法转化
		return 0
	}
	// dist: 单词 -> 序列长度，兼任 visited 防回头；起点自身也计入序列长度
	dist := map[string]int{beginWord: 1}
	q := []string{beginWord}
	for len(q) > 0 {
		cur := q[0]
		q = q[1:]
		if cur == endWord { // BFS 首次到达即最短，直接返回
			return dist[cur]
		}
		// 枚举每一位替换成 26 个字母，构造相邻单词
		b := []byte(cur)
		for i := 0; i < len(b); i++ {
			old := b[i]
			for c := byte('a'); c <= 'z'; c++ {
				if c == old {
					continue
				}
				b[i] = c
				nxt := string(b)
				if words[nxt] && dist[nxt] == 0 { // 在字典中且未访问 = 相邻节点
					dist[nxt] = dist[cur] + 1 // 入队即登记，杜绝重复扩展
					q = append(q, nxt)
				}
			}
			b[i] = old // 恢复该位，继续枚举下一位
		}
	}
	return 0 // 搜索耗尽仍不可达，说明不存在转化序列
}

