class DSU:
    def __init__(self, n):
        self.p = list(range(n))         # parent 数组，初始各自成集合
    def find(self, x):
        while self.p[x] != x:           # 路径压缩：边找边把节点挂到祖父
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x
    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self.p[ra] = rb             # 简单合并（可加按秩优化）
            return True
        return False

def solve(board):
    if not board or not board[0]:
        return
    m, n = len(board), len(board[0])
    dsu = DSU(m * n + 1)
    safe = m * n                        # 虚拟超级节点：代表边界安全区
    for i in range(m):
        for j in range(n):
            if board[i][j] != 'O':
                continue
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                dsu.union(i * n + j, safe)          # 边界 O 归入安全区
            if j + 1 < n and board[i][j+1] == 'O':
                dsu.union(i * n + j, i * n + j + 1) # 与右邻居合并
            if i + 1 < m and board[i+1][j] == 'O':
                dsu.union(i * n + j, (i + 1) * n + j)   # 与下邻居合并
    for i in range(m):                  # 第二趟：不在安全区集合的 O 全部翻转
        for j in range(n):
            if board[i][j] == 'O' and dsu.find(i * n + j) != dsu.find(safe):
                board[i][j] = 'X'

def solve(board):
    if not board or not board[0]:
        return
    m, n = len(board), len(board[0])

    def dfs(i, j):
        # 越界，或当前格不是未标记的安全 'O' 时停止
        if i < 0 or i >= m or j < 0 or j >= n or board[i][j] != 'O':
            return
        board[i][j] = '#'               # 占位：标记为与边界连通的安全 O
        dfs(i + 1, j); dfs(i - 1, j)    # 四方向扩散，标记整个安全连通块
        dfs(i, j + 1); dfs(i, j - 1)

    for i in range(m):                  # 左、右两条边上的 O 作为入口
        dfs(i, 0); dfs(i, n - 1)
    for j in range(n):                  # 上、下两条边上的 O 作为入口
        dfs(0, j); dfs(m - 1, j)

    for i in range(m):                  # 统一还原：'#' 恢复 'O'，剩余 'O' 翻 'X'
        for j in range(n):
            if board[i][j] == '#':
                board[i][j] = 'O'
            elif board[i][j] == 'O':
                board[i][j] = 'X'

from collections import deque

def solve(board):
    if not board or not board[0]:
        return
    m, n = len(board), len(board[0])
    q = deque()
    for i in range(m):                  # 四条边上的 O 全部作为种子
        for j in range(n):
            if (i in (0, m - 1) or j in (0, n - 1)) and board[i][j] == 'O':
                board[i][j] = '#'       # 入队即标记，防重复入队
                q.append((i, j))
    while q:
        i, j = q.popleft()
        for ni, nj in ((i+1, j), (i-1, j), (i, j+1), (i, j-1)):
            if 0 <= ni < m and 0 <= nj < n and board[ni][nj] == 'O':
                board[ni][nj] = '#'     # 扩散到的新 O 标记并入队
                q.append((ni, nj))
    for i in range(m):                  # 收尾：'#' 还原 'O'，剩余 'O' 翻 'X'
        for j in range(n):
            if board[i][j] == '#':
                board[i][j] = 'O'
            elif board[i][j] == 'O':
                board[i][j] = 'X'

