class Solution {
public:
    void solve(vector<vector<char>>& board) {
        int m = board.size(), n = board[0].size();
        // 只有边界上的 O 才可能不被围绕：从四条边的 O 出发 DFS 标记安全区
        for (int i = 0; i < m; ++i) {
            dfs(board, i, 0);      // 左边缘
            dfs(board, i, n - 1);  // 右边缘
        }
        for (int j = 0; j < n; ++j) {
            dfs(board, 0, j);      // 上边缘
            dfs(board, m - 1, j);  // 下边缘
        }
        // 统一还原：'#' 是与边界连通的安全 O，恢复为 'O'；剩余 'O' 全部被围绕，翻成 'X'
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (board[i][j] == '#') board[i][j] = 'O';
                else if (board[i][j] == 'O') board[i][j] = 'X';
            }
        }
    }

private:
    // 越界，或当前格不是未标记的安全 'O' 时停止
    void dfs(vector<vector<char>>& board, int i, int j) {
        if (i < 0 || i >= (int)board.size() || j < 0 || j >= (int)board[0].size()
            || board[i][j] != 'O') return;
        board[i][j] = '#';   // 占位：标记为与边界连通的安全 O
        dfs(board, i + 1, j);  // 向四方向扩散，标记整个安全连通块
        dfs(board, i - 1, j);
        dfs(board, i, j + 1);
        dfs(board, i, j - 1);
    }
};

problems.acmCodeCpp:
// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n m（网格行数、列数）
//   接下来 n 行：每行一个长度为 m 的字符串，由 'X' 和 'O' 组成
// 输出格式：n 行，每行为捕获被围绕区域后的网格字符串
#include <iostream>
#include <string>
#include <vector>

using namespace std;

int m, n;
vector<string> board;

// 越界，或当前格不是未标记的安全 'O' 时停止
void dfs(int i, int j) {
    if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] != 'O') return;
    board[i][j] = '#';               // 占位：标记为与边界连通的安全 O
    dfs(i + 1, j); dfs(i - 1, j);    // 四方向扩散整块安全区
    dfs(i, j + 1); dfs(i, j - 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> m >> n;
    board.resize(m);
    for (int i = 0; i < m; ++i) cin >> board[i];   // 每行一个 X/O 串

    for (int i = 0; i < m; ++i) {    // 左、右两条边上的 O 作为入口
        dfs(i, 0); dfs(i, n - 1);
    }
    for (int j = 0; j < n; ++j) {    // 上、下两条边上的 O 作为入口
        dfs(0, j); dfs(m - 1, j);
    }
    for (int i = 0; i < m; ++i) {    // 统一还原：'#' 恢复 'O'，剩余 'O' 翻 'X'
        for (int j = 0; j < n; ++j) {
            if (board[i][j] == '#') board[i][j] = 'O';
            else if (board[i][j] == 'O') board[i][j] = 'X';
        }
        cout << board[i] << "\n";    // 每行输出处理后的网格字符串
    }
    return 0;
}

