    dfs(i, j + 1); dfs(i, j - 1);
  };
  // 只有边界上的 O 才可能不被围绕：从四条边的 O 出发
  for (let i = 0; i < m; i++) { dfs(i, 0); dfs(i, n - 1); }
  for (let j = 0; j < n; j++) { dfs(0, j); dfs(m - 1, j); }
  // 统一还原：'#' 恢复 'O'，剩余 'O' 全部被围绕，翻成 'X'
  for (let i = 0; i < m; i++) {
