// 输入格式：
//   第一行：n m（节点数，节点值为 1..n；无向边数）
//   接下来 m 行：每行两个整数 u v，表示节点 u 与 v 相邻
// 输出格式：n 行，第 i 行为克隆图中节点 i 的邻居编号（空格分隔，顺序与输入一致；无邻居输出空行）
#include <iostream>
#include <unordered_map>
#include <vector>

using namespace std;

struct Node {
    int val;
    vector<Node*> neighbors;
    explicit Node(int v) : val(v) {}
};

int n, m;
vector<vector<int>> adj;            // 1..n 的原邻接表
unordered_map<int, Node*> visited;  // 原节点编号 -> 克隆节点，兼作 visited

// DFS 克隆：先创建克隆体并登记，再克隆邻居（先登记可防自环死循环）
Node* dfs(int u) {
    auto it = visited.find(u);
    if (it != visited.end()) return it->second;  // 已克隆过：直接复用克隆体，防环
    Node* c = new Node(u);
    visited[u] = c;                 // 先登记再展开邻居
    for (int v : adj[u]) {
        c->neighbors.push_back(dfs(v));  // 挂接邻居的克隆体
    }
    return c;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    adj.assign(n + 1, {});
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);        // 无向边双向挂接
        adj[v].push_back(u);
    }
    for (int u = 1; u <= n; ++u) {  // 输入保证连通，循环写法更稳
        if (!visited.count(u)) dfs(u);
    }
    for (int u = 1; u <= n; ++u) {  // 输出克隆图中各节点的邻居编号
        for (int k = 0; k < (int)visited[u]->neighbors.size(); ++k) {
            if (k) cout << ' ';
            cout << visited[u]->neighbors[k]->val;
        }
        cout << "\n";
    }
    return 0;
}

