    private Node dfs(Node cur, Map<Node, Node> visited) {
        if (visited.containsKey(cur)) return visited.get(cur);  // 已克隆过：直接复用
        Node clone = new Node(cur.val);
        visited.put(cur, clone);  // 先登记再展开邻居，环上不会重复创建
        for (Node nb : cur.neighbors) {
            clone.neighbors.add(dfs(nb, visited));  // 邻居的克隆体依次挂接
        }
        return clone;
    }
}

