                count += 1
                grid[i][j] = '0'        # 入队前先沉岛，防重复入队
                q = deque([(i, j)])
                while q:
                    x, y = q.popleft()
                    for nx, ny in ((x+1, y), (x-1, y), (x, y+1), (x, y-1)):
                        if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == '1':
                            grid[nx][ny] = '0'   # 扩散时同步沉岛
                            q.append((nx, ny))
