    def dfs(i, j):
        # 越界或踩到水（含已沉掉的岛）就停，等价于隐式 visited
        if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] != '1':
            return
        grid[i][j] = '0'                # 沉岛：先标记再向四方向扩散
        dfs(i + 1, j); dfs(i - 1, j)
        dfs(i, j + 1); dfs(i, j - 1)

    count = 0
    for i in range(m):                  # 扫描全图，每个未访问的 '1' 都是新岛
        for j in range(n):
            if grid[i][j] == '1':
                count += 1              # 发现新岛屿，计数 +1
                dfs(i, j)               # 沉掉整座岛，之后不会再遇到它
    return count

class DSU:
    def __init__(self, n):
        self.p = list(range(n))
    def find(self, x):
        while self.p[x] != x:           # 路径压缩
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x
    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self.p[ra] = rb             # 合并成功
            return True
        return False                    # 本就同集合

def numIslands(grid):
    m, n = len(grid), len(grid[0])
    dsu = DSU(m * n)
    island = sum(grid[i][j] == '1' for i in range(m) for j in range(n))
    for i in range(m):
        for j in range(n):
            if grid[i][j] != '1':
                continue
            if j + 1 < n and grid[i][j+1] == '1' and dsu.union(i*n+j, i*n+j+1):
                island -= 1             # 两个陆地块合一，岛数 -1
            if i + 1 < m and grid[i+1][j] == '1' and dsu.union(i*n+j, (i+1)*n+j):
                island -= 1
    return island

