from collections import defaultdict

def canFinish(numCourses, prerequisites):
    graph = defaultdict(list)
    for a, b in prerequisites:
        graph[b].append(a)              # 先修 b 才能修 a：建边 b -> a
    color = [0] * numCourses            # 0 未访问 / 1 递归栈中 / 2 已完成

    def dfs(u):
        color[u] = 1                    # 入栈
        for v in graph[u]:
            if color[v] == 1:           # 指向栈中节点：回边，有环
                return False
            if color[v] == 0 and not dfs(v):
                return False            # 后继子图有环，向上传递
        color[u] = 2                    # 出栈：u 及其整棵子树都安全
        return True

    return all(dfs(i) for i in range(numCourses) if color[i] == 0)

