class Solution {
public:
    bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {
        vector<vector<int>> graph(numCourses);  // 邻接表：先修课 -> 修完后可解锁的课列表
        vector<int> indeg(numCourses, 0);       // 入度表：每门课还差多少门先修课
        for (auto& p : prerequisites) {
            graph[p[1]].push_back(p[0]);        // [a, b] 表示先修 b 后修 a，建边 b -> a
            ++indeg[p[0]];                      // a 的先修需求 +1
        }
        queue<int> q;                           // 无先修的课先入队
        for (int i = 0; i < numCourses; ++i) {
            if (indeg[i] == 0) q.push(i);
        }
        int done = 0;                           // 已完成（出队）的课程数
        while (!q.empty()) {
            int cur = q.front();
            q.pop();
            ++done;
            for (int nxt : graph[cur]) {  // 修完 cur，它后继课程的先修需求各减一
                if (--indeg[nxt] == 0) q.push(nxt);  // 先修全部满足，解锁并入队
            }
        }
        return done == numCourses;  // 全部出队 = 无环；出不完说明图中有环
    }
};

