        for (int nxt : graph[cur]) {
            if (--indeg[nxt] == 0) q.push(nxt);  // 依赖清零，解锁入队
        }
    }
    cout << (done == n ? "true" : "false") << endl;  // 排不完 = 有环
    return 0;
}

