from collections import defaultdict

def findOrder(numCourses, prerequisites):
    graph = defaultdict(list)
    for a, b in prerequisites:
        graph[b].append(a)              # 先修 b 才能修 a：建边 b -> a
    color = [0] * numCourses            # 0 未访问 / 1 递归栈中 / 2 已完成
    post = []                           # DFS 后序完成序列

    def dfs(u):
        color[u] = 1                    # 入栈
        for v in graph[u]:
            if color[v] == 1:           # 回边：有环
                return False
            if color[v] == 0 and not dfs(v):
                return False            # 后继子图有环，向上传递
        color[u] = 2                    # 出栈
        post.append(u)                  # 回溯完成时记录后序
        return True

    for i in range(numCourses):
        if color[i] == 0 and not dfs(i):
            return []                   # 有环，无法安排
    return post[::-1]                   # 后序逆序 = 一个合法拓扑序

