from collections import defaultdict, deque

def calcEquation(equations, values, queries):
    graph = defaultdict(dict)           # a -> {b: a/b 的值}
    for (a, b), v in zip(equations, values):
        graph[a][b] = v                 # 正向边权 a/b = v
        graph[b][a] = 1 / v             # 反向边权 b/a = 1/v

    def bfs(src, dst):
        if src not in graph or dst not in graph:
            return -1.0                 # 未出现过的变量无定义
        q = deque([(src, 1.0)])         # (当前变量, 起点到它的累积乘积)
        visited = {src}                 # 每次查询独立建 visited
        while q:
            cur, acc = q.popleft()
            if cur == dst:              # 首达目标，累积乘积即商
                return acc
            for nxt, w in graph[cur].items():
                if nxt not in visited:
                    visited.add(nxt)
                    q.append((nxt, acc * w))   # 边权累乘传递
        return -1.0                     # 不可达：不同连通分量

    return [bfs(a, b) for a, b in queries]

from collections import defaultdict

def calcEquation(equations, values, queries):
    graph = defaultdict(dict)           # 邻接表：a -> {b: a/b 的值}
