        graph[a][b] = v                 # 正向边权 a/b
        graph[b][a] = 1 / v             # 反向边权 b/a，取倒数

    def dfs(cur, dst, acc, visited):
        if cur == dst:                  # 到达目标，累积乘积即为所求商
            return acc
        visited.add(cur)                # 标记当前节点，防止沿环死循环
        for nxt, w in graph[cur].items():
            if nxt not in visited:      # 只走向未访问的邻居
                r = dfs(nxt, dst, acc * w, visited)   # 边权累乘传递
                if r != -1.0:           # 找到可达路径，逐层原样返回
                    return r
        return -1.0                     # 所有分支都不通，无定义

    ans = []
    for a, b in queries:
        if a not in graph or b not in graph:
            ans.append(-1.0)            # 未出现过的变量无定义
        else:
            ans.append(dfs(a, b, 1.0, set()))   # a == b 时立刻返回 1.0
    return ans

class WDSU:
    def __init__(self):
        self.parent = {}                # 变量 -> 父变量
        self.weight = {}                # 变量到父变量的比值
    def add(self, x):
        if x not in self.parent:
            self.parent[x] = x
            self.weight[x] = 1.0
    def find(self, x):
        if self.parent[x] != x:         # 路径压缩：顺带把比值累乘成到根的比值
            root = self.find(self.parent[x])
            self.weight[x] *= self.weight[self.parent[x]]
            self.parent[x] = root
        return self.parent[x]
    def union(self, a, b, v):           # 已知 a / b = v
        self.add(a); self.add(b)
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self.parent[ra] = rb
            self.weight[ra] = v * self.weight[b] / self.weight[a]
    def query(self, a, b):
        if a not in self.parent or b not in self.parent:
            return -1.0
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            return -1.0                 # 不同连通分量
        return self.weight[a] / self.weight[b]   # 到根比值相除，根约掉

def calcEquation(equations, values, queries):
    dsu = WDSU()
    for (a, b), v in zip(equations, values):
        dsu.union(a, b, v)              # 每条等式合并一次
    return [dsu.query(a, b) for a, b in queries]

