class Solution {
public:
    vector<double> calcEquation(vector<vector<string>>& equations, vector<double>& values,
                                vector<vector<string>>& queries) {
        // 邻接表：a -> {b: a/b 的值}
        unordered_map<string, unordered_map<string, double>> graph;
        for (int i = 0; i < (int)equations.size(); ++i) {
            const string& a = equations[i][0];
            const string& b = equations[i][1];
            graph[a][b] = values[i];        // 正向边权 a/b
            graph[b][a] = 1.0 / values[i];  // 反向边权 b/a，取倒数
        }

        // DFS：cur 到 dst 的累积乘积即所求商；不通返回 -1
        function<double(const string&, const string&, double, unordered_set<string>&)> dfs =
            [&](const string& cur, const string& dst, double acc,
                unordered_set<string>& visited) -> double {
            if (cur == dst) return acc;  // 到达目标，累积乘积即为所求商
            visited.insert(cur);         // 标记当前节点，防止沿环死循环
            for (const auto& [nxt, w] : graph[cur]) {  // C++17 结构化绑定遍历邻居
                if (!visited.count(nxt)) {
                    double r = dfs(nxt, dst, acc * w, visited);  // 边权累乘传递
                    if (r != -1.0) return r;  // 找到可达路径，逐层原样返回
                }
            }
            return -1.0;  // 所有分支都不通，无定义
        };

        vector<double> ans;
        ans.reserve(queries.size());
        for (auto& q : queries) {
            const string& a = q[0];
            const string& b = q[1];
            if (!graph.count(a) || !graph.count(b)) {
                ans.push_back(-1.0);  // 未出现过的变量无定义
            } else {
                unordered_set<string> visited;
                ans.push_back(dfs(a, b, 1.0, visited));  // a == b 时立刻返回 1.0
            }
        }
        return ans;
    }
};

