        for (int i = 0; i < queries.size(); i++) {
            String a = queries.get(i).get(0), b = queries.get(i).get(1);
            if (!graph.containsKey(a) || !graph.containsKey(b)) {
                ans[i] = -1.0;  // 未出现过的变量无定义
            } else {
                ans[i] = dfs(a, b, 1.0, graph, new HashSet<>());  // a == b 时立刻返回 1.0
            }
        }
        return ans;
    }

    // DFS：cur 到 dst 的累积乘积即所求商；不通返回 -1
    private double dfs(String cur, String dst, double acc,
                       Map<String, Map<String, Double>> graph, Set<String> visited) {
        if (cur.equals(dst)) return acc;  // 到达目标，累积乘积即为所求商
        visited.add(cur);                 // 标记当前节点，防止沿环死循环
        for (Map.Entry<String, Double> e : graph.get(cur).entrySet()) {
            if (!visited.contains(e.getKey())) {
                double r = dfs(e.getKey(), dst, acc * e.getValue(), graph, visited);
                if (r != -1.0) return r;  // 找到可达路径，逐层原样返回
            }
        }
        return -1.0;  // 所有分支都不通，无定义
    }
}

