/**
 * @param {string[][]} equations
 * @param {number[]} values
 * @param {string[][]} queries
 * @return {number[]}
 */
var calcEquation = function (equations, values, queries) {
  const graph = new Map();  // 邻接表：a -> Map(b -> a/b 的值)
  for (let i = 0; i < equations.length; i++) {
    const [a, b] = equations[i];
    if (!graph.has(a)) graph.set(a, new Map());
    if (!graph.has(b)) graph.set(b, new Map());
    graph.get(a).set(b, values[i]);      // 正向边权 a/b
    graph.get(b).set(a, 1 / values[i]);  // 反向边权 b/a，取倒数
  }
  // DFS：cur 到 dst 的累积乘积即所求商；不通返回 -1
  const dfs = (cur, dst, acc, visited) => {
    if (cur === dst) return acc;  // 到达目标，累积乘积即为所求商
    visited.add(cur);             // 标记当前节点，防止沿环死循环
    for (const [nxt, w] of graph.get(cur)) {
      if (!visited.has(nxt)) {
        const r = dfs(nxt, dst, acc * w, visited);  // 边权累乘传递
        if (r !== -1) return r;  // 找到可达路径，逐层原样返回
      }
    }
    return -1;  // 所有分支都不通，无定义
  };
  return queries.map(([a, b]) => {
    if (!graph.has(a) || !graph.has(b)) return -1;  // 未出现过的变量无定义
    return dfs(a, b, 1.0, new Set());  // a == b 时立刻返回 1.0
  });
};

