		}
		if graph[b] == nil {
			graph[b] = map[string]float64{}
		}
		graph[a][b] = values[i]     // 正向边权 a/b
		graph[b][a] = 1 / values[i] // 反向边权取倒数
	}
	// DFS：cur 到 dst 的累积乘积即所求商；不通返回 -1
	var dfs func(cur, dst string, acc float64, visited map[string]bool) float64
	dfs = func(cur, dst string, acc float64, visited map[string]bool) float64 {
