			return acc
		}
		visited[cur] = true // 标记当前节点，防止沿环死循环
		for nxt, w := range graph[cur] {
			if !visited[nxt] {
				if r := dfs(nxt, dst, acc*w, visited); r != -1 { // 边权累乘传递
					return r // 找到可达路径，逐层原样返回
				}
			}
		}
		return -1 // 所有分支都不通，无定义
	}
	ans := make([]float64, len(queries))
	for i, q := range queries {
		a, b := q[0], q[1]
		if graph[a] == nil || graph[b] == nil {
			ans[i] = -1 // 未出现过的变量无定义
		} else {
			ans[i] = dfs(a, b, 1, map[string]bool{}) // a == b 时立刻返回 1
		}
	}
	return ans
}

