def pacificAtlantic(heights):
    if not heights or not heights[0]:
        return []
    m, n = len(heights), len(heights[0])

    def can_reach(i, j, to_pacific):
        # 正向模拟：水从 (i,j) 只流向不高过自己的邻格
        stack = [(i, j)]
        seen = {(i, j)}                 # 每次搜索独立的 visited
        while stack:
            x, y = stack.pop()
            if to_pacific and (x == 0 or y == 0):
                return True             # 到达第一行/列：入太平洋
            if not to_pacific and (x == m - 1 or y == n - 1):
                return True             # 到达最后一行/列：入大西洋
            for nx, ny in ((x+1, y), (x-1, y), (x, y+1), (x, y-1)):
                if (0 <= nx < m and 0 <= ny < n and (nx, ny) not in seen
                        and heights[nx][ny] <= heights[x][y]):
                    seen.add((nx, ny))
                    stack.append((nx, ny))
        return False

    ans = []
    for i in range(m):
        for j in range(n):
            if can_reach(i, j, True) and can_reach(i, j, False):
                ans.append([i, j])      # 双海可达
    return ans

