class Solution {
public:
    vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {
        int m = heights.size(), n = heights[0].size();
        vector<vector<char>> pac(m, vector<char>(n, 0));  // 太平洋能逆向『爬坡』到达的格子
        vector<vector<char>> atl(m, vector<char>(n, 0));  // 大西洋对应的可达标记

        // 逆向 DFS：从海洋边界出发，向『不低于当前格』的邻格扩散，海水才能倒灌漫到这里
        function<void(int, int, vector<vector<char>>&)> dfs =
            [&](int i, int j, vector<vector<char>>& seen) {
            if (seen[i][j]) return;  // 已标记过，剪枝
            seen[i][j] = 1;          // 标记当前格的水可以流到该海洋
            static const int di[] = {1, -1, 0, 0}, dj[] = {0, 0, 1, -1};
            for (int d = 0; d < 4; ++d) {
                int ni = i + di[d], nj = j + dj[d];
                // 逆向爬坡：相邻格不低于当前格，等高也能流
                if (ni >= 0 && ni < m && nj >= 0 && nj < n
                    && heights[ni][nj] >= heights[i][j]) {
                    dfs(ni, nj, seen);
                }
            }
        };

        for (int i = 0; i < m; ++i) {  // 太平洋入口：第一列；大西洋入口：最后一列
            dfs(i, 0, pac);
            dfs(i, n - 1, atl);
        }
        for (int j = 0; j < n; ++j) {  // 太平洋入口：第一行；大西洋入口：最后一行
            dfs(0, j, pac);
            dfs(m - 1, j, atl);
        }

        vector<vector<int>> ans;
        for (int i = 0; i < m; ++i) {  // 两个可达集合的交集即答案，按行优先收集
            for (int j = 0; j < n; ++j) {
                if (pac[i][j] && atl[i][j]) ans.push_back({i, j});
            }
        }
        return ans;
    }
};

