// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n m（网格行数、列数）
//   接下来 n 行：每行 m 个整数（海拔），空格分隔
// 输出格式：每行一个坐标 i j（既能流入太平洋又能流入大西洋的格子），按行优先排序
#include <iostream>
#include <vector>

using namespace std;

int n, m;
vector<vector<int>> h;     // 海拔网格
vector<vector<char>> pac;  // 太平洋能逆向爬坡到达的格子
vector<vector<char>> atl;  // 大西洋对应的可达标记

// 逆向 DFS：从海洋边界出发，向『不低于当前格』的邻格扩散
void dfs(int i, int j, vector<vector<char>>& seen) {
    if (seen[i][j]) return;  // 已标记过，剪枝
    seen[i][j] = 1;          // 标记当前格的水可以流到该海洋
    int di[] = {1, -1, 0, 0}, dj[] = {0, 0, 1, -1};
    for (int d = 0; d < 4; ++d) {
        int ni = i + di[d], nj = j + dj[d];
        // 逆向爬坡：邻格不低于当前格，等高也能流
        if (ni >= 0 && ni < n && nj >= 0 && nj < m && h[ni][nj] >= h[i][j]) {
            dfs(ni, nj, seen);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    h.assign(n, vector<int>(m));
    pac.assign(n, vector<char>(m, 0));
    atl.assign(n, vector<char>(m, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) cin >> h[i][j];
    }

    for (int i = 0; i < n; ++i) {  // 左列入太平洋、右列入大西洋
        dfs(i, 0, pac); dfs(i, m - 1, atl);
    }
    for (int j = 0; j < m; ++j) {  // 上行入太平洋、下行入大西洋
        dfs(0, j, pac); dfs(n - 1, j, atl);
    }
    for (int i = 0; i < n; ++i) {  // 按行优先输出两个可达集合的交集
        for (int j = 0; j < m; ++j) {
            if (pac[i][j] && atl[i][j]) cout << i << ' ' << j << "\n";
        }
    }
    return 0;
}

