from collections import deque

def maxAreaOfIsland(grid):
    m, n = len(grid), len(grid[0])
    ans = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:         # 发现新岛屿
                grid[i][j] = 0
                q = deque([(i, j)])
                area = 1                # 起点先计数
                while q:
                    x, y = q.popleft()
                    for nx, ny in ((x+1, y), (x-1, y), (x, y+1), (x, y-1)):
                        if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 1:
                            grid[nx][ny] = 0   # 沉岛与计数同步
                            area += 1
                            q.append((nx, ny))
                ans = max(ans, area)    # 一座岛统计完再比较
    return ans

def maxAreaOfIsland(grid):
    m, n = len(grid), len(grid[0])

    def dfs(i, j):
        # 越界或踩到水/已访问格返回 0，不再贡献面积
        if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] != 1:
            return 0
        grid[i][j] = 0                  # 沉岛：先标记，保证每格只统计一次
        # 当前格 1 + 四个方向连通块面积之和 = 整座岛的面积
        return 1 + dfs(i + 1, j) + dfs(i - 1, j) + dfs(i, j + 1) + dfs(i, j - 1)

    ans = 0
    for i in range(m):                  # 扫描全图，每个连通块算一次面积
        for j in range(n):
            if grid[i][j] == 1:
                ans = max(ans, dfs(i, j))   # 保留所有岛屿面积的最大值
    return ans

class DSU:
    def __init__(self, n):
        self.p = list(range(n))
        self.size = [1] * n             # 每个根的集合大小
    def find(self, x):
        while self.p[x] != x:           # 路径压缩
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x
    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return 0                    # 已同集合，大小不变
        if self.size[ra] < self.size[rb]:   # 小挂大（按大小合并）
            ra, rb = rb, ra
        self.p[rb] = ra
        self.size[ra] += self.size[rb]  # 大小累加到新根
        return self.size[ra]

def maxAreaOfIsland(grid):
    m, n = len(grid), len(grid[0])
    dsu = DSU(m * n)
    ans = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] != 1:
                continue
            ans = max(ans, 1)           # 单格也是一座岛
            if j + 1 < n and grid[i][j+1] == 1:
                ans = max(ans, dsu.union(i*n+j, i*n+j+1))
            if i + 1 < m and grid[i+1][j] == 1:
                ans = max(ans, dsu.union(i*n+j, (i+1)*n+j))
    return ans

