        return 1 + dfs(i + 1, j) + dfs(i - 1, j) + dfs(i, j + 1) + dfs(i, j - 1)

    ans = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                ans = max(ans, dfs(i, j))   # 各岛面积取最大
