// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n m（网格行数、列数）
//   接下来 n 行：每行 m 个整数 0/1（空格分隔；1 陆地，0 水）
// 输出格式：一个整数，最大岛屿面积
#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

int n, m;
vector<vector<int>> grid;

// 越界或踩到水/已访问格返回 0，不再贡献面积
int dfs(int i, int j) {
    if (i < 0 || i >= n || j < 0 || j >= m || grid[i][j] != 1) return 0;
    grid[i][j] = 0;  // 沉岛：每格只统计一次
    // 当前格 1 + 四个方向连通块面积之和 = 整座岛的面积
    return 1 + dfs(i + 1, j) + dfs(i - 1, j) + dfs(i, j + 1) + dfs(i, j - 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    grid.assign(n, vector<int>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) cin >> grid[i][j];
    }

    int ans = 0;
    for (int i = 0; i < n; ++i) {  // 扫描全图，各岛面积取最大
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 1) ans = max(ans, dfs(i, j));
        }
    }
    cout << ans << endl;
    return 0;
}

