    q = deque()                         # 队列存当前这一分钟所有腐烂橘子
    fresh = 0                           # 新鲜橘子计数，用于最终判定
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2:
                q.append((i, j))        # 多源 BFS：所有源点同时入队
