                fresh += 1

    minutes = 0                         # 经过的分钟数 = BFS 扩散的层数
    while q and fresh:                  # 没有新鲜橘子后无需继续扩散
        minutes += 1                    # 处理一轮队列 = 过去一分钟
        for _ in range(len(q)):         # 固定本轮长度，逐个处理同层节点
            i, j = q.popleft()
