                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1:
                    grid[ni][nj] = 2    # 感染同时充当 visited 标记
                    fresh -= 1
                    q.append((ni, nj))
    return minutes if fresh == 0 else -1   # 仍有新鲜橘子则永远烂不完

