class Solution {
public:
    int orangesRotting(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        const int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        queue<pair<int, int>> q;  // 队列存当前这一分钟所有腐烂橘子
        int fresh = 0;            // 新鲜橘子计数，用于最终判定
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 2) q.push({i, j});  // 多源 BFS：所有源点同时入队
                else if (grid[i][j] == 1) ++fresh;
            }
        }

        int minutes = 0;                   // 经过的分钟数 = BFS 扩散的层数
        while (!q.empty() && fresh > 0) {  // 没有新鲜橘子后无需继续扩散
            ++minutes;                     // 处理一轮队列 = 过去一分钟
            // 固定本轮长度 sz，逐个处理同一分钟的腐烂橘子（同层节点）
            for (int sz = (int)q.size(); sz > 0; --sz) {
                auto [i, j] = q.front();
                q.pop();
                for (auto& d : dirs) {     // 感染四邻中值仍为 1 的新鲜橘子
                    int ni = i + d[0], nj = j + d[1];
                    if (ni < 0 || ni >= m || nj < 0 || nj >= n || grid[ni][nj] != 1) continue;
                    grid[ni][nj] = 2;      // 感染同时充当 visited 标记
                    --fresh;
                    q.push({ni, nj});
                }
            }
        }
        return fresh == 0 ? minutes : -1;  // 仍有新鲜橘子则永远烂不完
    }
};

