class Solution {
    public int orangesRotting(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        Queue<int[]> q = new ArrayDeque<>();  // 队列存当前这一分钟所有腐烂橘子
        int fresh = 0;                        // 新鲜橘子计数，用于最终判定
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 2) q.offer(new int[]{i, j});  // 多源 BFS：所有源点同时入队
                else if (grid[i][j] == 1) fresh++;
            }
        }

        int minutes = 0;                     // 经过的分钟数 = BFS 扩散的层数
        while (!q.isEmpty() && fresh > 0) {  // 没有新鲜橘子后无需继续扩散
            minutes++;                       // 处理一轮队列 = 过去一分钟
            for (int sz = q.size(); sz > 0; sz--) {  // 固定本轮长度，逐个处理同层节点
                int[] cur = q.poll();
                for (int[] d : dirs) {       // 感染四邻中值仍为 1 的新鲜橘子
                    int ni = cur[0] + d[0], nj = cur[1] + d[1];
                    if (ni < 0 || ni >= m || nj < 0 || nj >= n || grid[ni][nj] != 1) continue;
                    grid[ni][nj] = 2;        // 感染同时充当 visited 标记
                    fresh--;
                    q.offer(new int[]{ni, nj});
                }
            }
        }
        return fresh == 0 ? minutes : -1;    // 仍有新鲜橘子则永远烂不完
    }
}

