func orangesRotting(grid [][]int) int {
	m, n := len(grid), len(grid[0])
	dirs := [4][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	q := [][2]int{} // 队列存当前这一分钟所有腐烂橘子
	fresh := 0      // 新鲜橘子计数，用于最终判定
	for i := 0; i < m; i++ {
		for j := 0; j < n; j++ {
			if grid[i][j] == 2 {
				q = append(q, [2]int{i, j}) // 多源 BFS：所有源点同时入队
			} else if grid[i][j] == 1 {
				fresh++
			}
		}
	}

	minutes := 0                  // 经过的分钟数 = BFS 扩散的层数
	for len(q) > 0 && fresh > 0 { // 没有新鲜橘子后无需继续扩散
		minutes++ // 处理一轮队列 = 过去一分钟
		// 固定本轮长度 sz，逐个处理同一分钟的腐烂橘子（同层节点）
		for sz := len(q); sz > 0; sz-- {
			cur := q[0]
			q = q[1:]
			for _, d := range dirs { // 感染四邻中值仍为 1 的新鲜橘子
				ni, nj := cur[0]+d[0], cur[1]+d[1]
