					continue
				}
				grid[ni][nj] = 2 // 感染同时充当 visited 标记
				fresh--
				q = append(q, [2]int{ni, nj})
			}
		}
	}
	if fresh > 0 {
		return -1 // 仍有新鲜橘子则永远烂不完
	}
	return minutes
}
